# --------------------------------------------------------------------------- #
# Protocol constants
# --------------------------------------------------------------------------- #
SOCKS_VERSION = 5

AUTH_NONE = 0x00
AUTH_NO_ACCEPTABLE = 0xFF

CMD_CONNECT = 0x01
CMD_BIND = 0x02
CMD_UDP_ASSOCIATE = 0x03

ATYP_IPV4 = 0x01
ATYP_DOMAIN = 0x03
ATYP_IPV6 = 0x04

REP_SUCCEEDED = 0x00
REP_GENERAL_FAILURE = 0x01
REP_NOT_ALLOWED = 0x02
REP_NETWORK_UNREACHABLE = 0x03
REP_HOST_UNREACHABLE = 0x04
REP_CONNECTION_REFUSED = 0x05
REP_TTL_EXPIRED = 0x06
REP_COMMAND_NOT_SUPPORTED = 0x07
REP_ATYP_NOT_SUPPORTED = 0x08

BUFSIZE = 64 * 1024
MAX_CONNECT_ATTEMPTS = 4  # how many resolved addresses we try for one connection

#: Default block list of the SOCKS5 server.  Besides the loopback networks it
#: contains the "unspecified" addresses (connecting to 0.0.0.0 / :: reaches the
#: local host on most systems) and the name "localhost" (and therefore
#: ``*.localhost``).  Extend it with ``DEFAULT_BLOCK_LIST + ("10.0.0.0/8",)``.
DEFAULT_BLOCK_LIST: Tuple[str, ...] = (
    "127.0.0.0/8",
    "::1/128",
    "0.0.0.0/8",
    "::/128",
    "localhost",
)

IPAddress = (ipaddress.IPv4Address, ipaddress.IPv6Address)
IPNetwork = (ipaddress.IPv4Network, ipaddress.IPv6Network)


# --------------------------------------------------------------------------- #
# Small helpers
# --------------------------------------------------------------------------- #
def _errnos(*names: str) -> frozenset:
    return frozenset(getattr(errno, n) for n in names if hasattr(errno, n))


_NET_UNREACHABLE = _errnos("ENETUNREACH", "ENETDOWN", "WSAENETUNREACH", "WSAENETDOWN")
_HOST_UNREACHABLE = _errnos("EHOSTUNREACH", "EHOSTDOWN", "WSAEHOSTUNREACH", "WSAEHOSTDOWN")
_REFUSED = _errnos("ECONNREFUSED", "WSAECONNREFUSED")
_TIMED_OUT = _errnos("ETIMEDOUT", "WSAETIMEDOUT")
_DENIED = _errnos("EACCES", "EPERM", "WSAEACCES")


def _reply_code_for(exc: BaseException) -> int:
    """Map an exception raised while connecting to a SOCKS5 reply code."""
    if isinstance(exc, (asyncio.TimeoutError, TimeoutError)):
        return REP_TTL_EXPIRED
    if isinstance(exc, ConnectionRefusedError):
        return REP_CONNECTION_REFUSED
    if isinstance(exc, socket.gaierror):
        return REP_HOST_UNREACHABLE
    if isinstance(exc, OSError):
        code = exc.errno
        if code in _NET_UNREACHABLE:
            return REP_NETWORK_UNREACHABLE
        if code in _HOST_UNREACHABLE:
            return REP_HOST_UNREACHABLE
        if code in _REFUSED:
            return REP_CONNECTION_REFUSED
        if code in _TIMED_OUT:
            return REP_TTL_EXPIRED
        if code in _DENIED:
            return REP_NOT_ALLOWED
    return REP_GENERAL_FAILURE


def _parse_ip(value) -> Optional[ipaddress._BaseAddress]:
    if isinstance(value, IPAddress):
        return value
    try:
        return ipaddress.ip_address(str(value).split("%", 1)[0])  # drop IPv6 scope id
    except ValueError:
        return None


def _unmap(ip):
    """Turn ::ffff:a.b.c.d into a.b.c.d."""
    if ip.version == 6 and ip.ipv4_mapped is not None:
        return ip.ipv4_mapped
    return ip


def _pack_addr(ip) -> bytes:
    return (b"\x01" if ip.version == 4 else b"\x04") + ip.packed


def _build_reply(rep: int, ip=None, port: int = 0) -> bytes:
    if ip is None:
        ip = ipaddress.IPv4Address(0)
    return bytes([SOCKS_VERSION, rep, 0x00]) + _pack_addr(ip) + port.to_bytes(2, "big")


def _fmt_host(host: str, port: int) -> str:
    return f"[{host}]:{port}" if ":" in host else f"{host}:{port}"


def _fmt_addr(addr) -> str:
    if not addr:
        return "?"
    return _fmt_host(str(addr[0]), addr[1])


def _describe(exc: BaseException) -> str:
    if isinstance(exc, (asyncio.TimeoutError, TimeoutError)):
        return "timeout"
    if isinstance(exc, asyncio.IncompleteReadError):
        return "peer closed during handshake"
    return f"{type(exc).__name__}: {exc}" if str(exc) else type(exc).__name__


def _is_safe_name(name: str) -> bool:
    """A usable destination name: not empty, no control characters, no whitespace.

    Applied to the *decoded* text.  Underscores, hyphens and non-ASCII (IDN)
    letters are fine; newlines, NULs, tabs, spaces and other invisible
    characters are not (they would forge log lines and are never valid in a
    host name).
    """
    return bool(name) and name.isprintable() and " " not in name


def _interleave_families(addresses: list) -> list:
    """Alternate IP families, keeping the original order inside each family.

    getaddrinfo() lists addresses in preference order, often several IPv6 ones
    first.  Trying only the first few of those on a host without working IPv6
    would never reach IPv4 (compare RFC 8305, section 4).
    """
    if not addresses:
        return []
    first = addresses[0].version
    a = [x for x in addresses if x.version == first]
    b = [x for x in addresses if x.version != first]
    out = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            out.append(a[i])
        if i < len(b):
            out.append(b[i])
    return out


def _check_target(host: str, port: int) -> Tuple[str, int]:
    host = str(host).strip()
    if host.startswith("[") and host.endswith("]"):
        host = host[1:-1]
    if not _is_safe_name(host):
        raise ValueError(f"invalid host name: {host!r}")
    if not 0 < int(port) < 65536:
        raise ValueError(f"invalid target port: {port}")
    return host, int(port)


def _tune_socket(writer: asyncio.StreamWriter) -> None:
    """Enable TCP keep-alive so the OS eventually notices vanished peers."""
    sock = writer.get_extra_info("socket")
    if sock is None:
        return
    try:
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
        for name, value in (("TCP_KEEPIDLE", 60), ("TCP_KEEPINTVL", 15), ("TCP_KEEPCNT", 4)):
            opt = getattr(socket, name, None)
            if opt is not None:
                sock.setsockopt(socket.IPPROTO_TCP, opt, value)
    except OSError:
        pass


async def _close_writer(writer: Optional[asyncio.StreamWriter], timeout: float) -> None:
    """Close a stream: flush + FIN if the peer cooperates, abort otherwise."""
    if writer is None:
        return
    transport = writer.transport
    try:
        writer.close()
        await asyncio.wait_for(writer.wait_closed(), timeout)
    except asyncio.CancelledError:
        transport.abort()
        raise
    except Exception:
        transport.abort()


class _Reject(Exception):
    """Carries a SOCKS5 reply code."""

    def __init__(self, code: int, detail: str = ""):
        super().__init__(detail)
        self.code = code
        self.detail = detail


class _LRUSet:
    """Tiny bounded set that forgets the least recently added entries."""

    def __init__(self, capacity: int):
        self._d: "OrderedDict" = OrderedDict()
        self._cap = capacity

    def __contains__(self, key) -> bool:
        return key in self._d

    def add(self, key) -> bool:
        """Add/refresh *key*; return True if it was not present."""
        new = key not in self._d
        self._d[key] = None
        self._d.move_to_end(key)
        if len(self._d) > self._cap:
            self._d.popitem(last=False)
        return new


class _Activity:
    """Shared 'last traffic' clock of one relayed connection (both directions)."""

    def __init__(self, loop: asyncio.AbstractEventLoop, idle_timeout: float):
        self._loop = loop
        self._idle = idle_timeout
        self.deadline = loop.time() + idle_timeout

    def touch(self) -> None:
        self.deadline = self._loop.time() + self._idle

    def remaining(self) -> float:
        return self.deadline - self._loop.time()


# --------------------------------------------------------------------------- #
# Block list and name resolution
# --------------------------------------------------------------------------- #
class _BlockList:
    """CIDR networks / single IPs and host names that must not be reached."""

    def __init__(self, entries: Iterable):
        self.networks: List = []
        self.names: List[str] = []
        for entry in entries:
            if isinstance(entry, IPNetwork):
                self.networks.append(entry)
            elif isinstance(entry, IPAddress):
                self.networks.append(ipaddress.ip_network(entry))
            else:
                text = str(entry).strip()
                if not text:
                    continue
                try:
                    self.networks.append(ipaddress.ip_network(text, strict=False))
                except ValueError:
                    self.names.append(text.lower().rstrip("."))

    def is_ip_blocked(self, ip) -> bool:
        candidates = [ip]
        if ip.version == 6 and ip.ipv4_mapped is not None:
            candidates.append(ip.ipv4_mapped)
        for cand in candidates:
            for net in self.networks:
                if cand.version == net.version and cand in net:
                    return True
        return False

    def is_name_blocked(self, name: str) -> bool:
        name = name.lower().rstrip(".")
        return any(name == b or name.endswith("." + b) for b in self.names)


async def _default_resolver(host: str) -> Sequence[str]:
    loop = asyncio.get_running_loop()
    infos = await loop.getaddrinfo(host, None, type=socket.SOCK_STREAM)
    return [info[4][0] for info in infos]


Resolver = Callable[[str], Awaitable[Sequence[str]]]


# --------------------------------------------------------------------------- #
# Shared datagram protocol
# --------------------------------------------------------------------------- #
class _UdpProtocol(asyncio.DatagramProtocol):
    def __init__(self, on_datagram, on_error=None):
        self._on_datagram = on_datagram
        self._on_error = on_error

    def datagram_received(self, data, addr):
        self._on_datagram(data, addr)

    def error_received(self, exc):  # ICMP errors etc.: UDP is best effort
        if self._on_error is not None:
            self._on_error(exc)


# --------------------------------------------------------------------------- #
# Base class of all services
# --------------------------------------------------------------------------- #
class _Service:
    """Config, logging, name resolution and TCP relaying shared by all services."""

    def __init__(self, *, verbose, block_list, dns_timeout, idle_timeout, close_timeout,
                 resolver, connect_timeout=15.0, max_connections=1024):
        self.verbose = verbose
        self.block = _BlockList(DEFAULT_BLOCK_LIST if block_list is None else block_list)
        self.dns_timeout = dns_timeout
        self.idle_timeout = idle_timeout
        self.close_timeout = close_timeout
        self.connect_timeout = connect_timeout
        self.max_connections = max_connections
        self._resolver: Resolver = resolver or _default_resolver
        self._server: Optional[asyncio.AbstractServer] = None
        self._tasks: set = set()

    # -- public API --------------------------------------------------------- #
    @property
    def sockets(self):
        """The listening sockets (e.g. to find out an ephemeral port)."""
        return self._server.sockets if self._server else ()

    async def close(self) -> None:
        """Stop listening and gracefully tear down every live connection."""
        if self._server is not None:
            self._server.close()  # stop accepting
        tasks = list(self._tasks)
        for t in tasks:
            t.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        if self._server is not None:
            try:
                await asyncio.wait_for(self._server.wait_closed(), self.close_timeout)
            except (asyncio.TimeoutError, OSError):
                pass

    # -- logging ------------------------------------------------------------ #
    def log(self, message: str) -> None:
        if self.verbose:
            if not message.isprintable():  # peer-controlled text must not forge log lines
                message = "".join(c if c.isprintable() else c.encode("unicode_escape").decode("ascii")
                                  for c in message)
            try:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} {message}", flush=True)
            except (OSError, ValueError):  # stdout closed / broken pipe: logging is best effort
                pass

    # -- name resolution + block list --------------------------------------- #
    async def resolve_allowed(self, host: str, ip) -> list:
        """Return the non-blocked addresses of *host*, or raise _Reject."""
        if ip is None and self.block.is_name_blocked(host):
            raise _Reject(REP_NOT_ALLOWED, "name is blocked")
        if ip is not None:
            candidates = [ip]
        else:
            try:
                raw = await asyncio.wait_for(self._resolver(host), self.dns_timeout)
                if isinstance(raw, str):  # a single address instead of a list
                    raw = [raw]
                candidates = []
                for item in raw:
                    parsed = _parse_ip(item)
                    if parsed is not None and parsed not in candidates:
                        candidates.append(parsed)
            except (asyncio.TimeoutError, OSError, UnicodeError, ValueError) as exc:
                raise _Reject(REP_HOST_UNREACHABLE, f"resolution failed: {_describe(exc)}")
            except Exception as exc:  # a custom resolver may raise anything (or return junk)
                raise _Reject(REP_GENERAL_FAILURE, f"resolver error: {exc!r}")
            if not candidates:
                raise _Reject(REP_HOST_UNREACHABLE, "no addresses")
        allowed = [_unmap(c) for c in candidates if not self.block.is_ip_blocked(c)]
        if not allowed:
            raise _Reject(REP_NOT_ALLOWED, "address is blocked")
        return _interleave_families(allowed)

    # -- TCP listening / per-connection task -------------------------------- #
    async def _listen(self, addr, port: int, backlog: int, what: str) -> None:
        self._server = await asyncio.start_server(
            self._on_client, addr or None, port, backlog=backlog)
        for sock in self._server.sockets:
            self.log(f"{what} listening on {_fmt_addr(sock.getsockname())}")

    async def _handle(self, reader, writer, who: str) -> None:
        raise NotImplementedError

    async def _on_client(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter) -> None:
        task = asyncio.current_task()
        if task is not None:
            self._tasks.add(task)
            task.add_done_callback(self._tasks.discard)
        who = _fmt_addr(writer.get_extra_info("peername"))
        try:
            if len(self._tasks) > self.max_connections:
                self.log(f"{who} rejected: connection limit ({self.max_connections}) reached")
                return
            _tune_socket(writer)
            await self._handle(reader, writer, who)
        except asyncio.CancelledError:
            raise
        except (asyncio.IncompleteReadError, ConnectionError, asyncio.TimeoutError, OSError) as exc:
            self.log(f"{who} dropped: {_describe(exc)}")
        except Exception as exc:  # never let a bug leak out of the handler
            self.log(f"{who} internal error: {exc!r}")
        finally:
            await _close_writer(writer, self.close_timeout)

    # -- outgoing connection + relay ---------------------------------------- #
    async def _open_upstream(self, addresses: list, port: int):
        """Try the addresses in turn; return (reader, writer) or raise the last error."""
        last: BaseException = OSError("no address to connect to")
        for address in addresses[:MAX_CONNECT_ATTEMPTS]:
            try:
                return await asyncio.wait_for(
                    asyncio.open_connection(str(address), port), self.connect_timeout)
            except (OSError, asyncio.TimeoutError) as exc:
                last = exc
        raise last

    async def _relay(self, c_reader, c_writer, u_reader, u_writer):
        loop = asyncio.get_running_loop()
        activity = _Activity(loop, self.idle_timeout)
        stats = [0, 0]
        t1 = loop.create_task(self._pipe(c_reader, u_writer, activity, stats, 0))
        t2 = loop.create_task(self._pipe(u_reader, c_writer, activity, stats, 1))
        try:
            await asyncio.wait({t1, t2}, return_when=asyncio.FIRST_EXCEPTION)
        finally:
            for t in (t1, t2):
                if not t.done():
                    t.cancel()
            results = await asyncio.gather(t1, t2, return_exceptions=True)
        reason = "closed"
        for res in results:
            if isinstance(res, BaseException) and not isinstance(res, asyncio.CancelledError):
                reason = "idle timeout" if isinstance(res, (asyncio.TimeoutError, TimeoutError)) \
                    else _describe(res)
                break
        return stats[0], stats[1], reason

    async def _pipe(self, reader, writer, activity: _Activity, stats: list, idx: int) -> None:
        """Copy reader -> writer.  Idle means *no traffic in either direction*."""
        while True:
            remaining = activity.remaining()
            if remaining <= 0:
                raise asyncio.TimeoutError()
            try:
                data = await asyncio.wait_for(reader.read(BUFSIZE), remaining)
            except asyncio.TimeoutError:
                continue  # the other direction may have extended the deadline
            if not data:
                break
            activity.touch()
            writer.write(data)
            # A peer that stops reading must not pin us (and our memory) forever.
            await asyncio.wait_for(writer.drain(), self.idle_timeout)
            activity.touch()
            stats[idx] += len(data)
        # Propagate EOF as a half-close; the other direction may still be active.
        try:
            if writer.can_write_eof():
                writer.write_eof()
        except OSError:
            pass


# --------------------------------------------------------------------------- #
# SOCKS5: UDP relay
# --------------------------------------------------------------------------- #
def _parse_udp_header(data: bytes):
    """Return (host, ip_or_None, port, payload) or None for malformed/unsupported."""
    if len(data) < 4 or data[2] != 0:  # FRAG != 0: fragmentation not supported
        return None
    atyp = data[3]
    ip = None
    if atyp == ATYP_IPV4:
        if len(data) < 10:
            return None
        ip = ipaddress.IPv4Address(data[4:8])
        host, off = str(ip), 8
    elif atyp == ATYP_IPV6:
        if len(data) < 22:
            return None
        ip = ipaddress.IPv6Address(data[4:20])
        host, off = str(ip), 20
    elif atyp == ATYP_DOMAIN:
        if len(data) < 5:
            return None
        n = data[4]
        raw = data[5:5 + n]
        if n == 0 or len(raw) != n:
            return None
        try:
            host = raw.decode("utf-8")
        except UnicodeDecodeError:
            return None
        if not _is_safe_name(host):
            return None
        ip = _parse_ip(host)
        off = 5 + n
    else:
        return None
    if len(data) < off + 2:
        return None
    port = int.from_bytes(data[off:off + 2], "big")
    return host, ip, port, data[off + 2:]


class _UdpRelay:
    """State of one SOCKS5 UDP ASSOCIATE.

    * a *client-facing* socket, bound to the local address the client reached
      us on, only accepts datagrams from the client's IP (the port is locked to
      the first datagram);
    * *remote-facing* sockets (one per IP family, created lazily) talk to the
      destinations.  Replies are only forwarded from peers the client has sent
      something to.
    """

    MAX_PENDING = 64     # max concurrent name resolutions / socket creations
    DNS_TTL = 60.0
    DNS_CACHE_MAX = 128

    def __init__(self, server: "Socks5Server", who: str, client_ip, local_ip):
        self._srv = server
        self._who = who
        self._client_ip = client_ip
        self.bind_ip = local_ip
        self.bind_port = 0
        self._client_tr: Optional[asyncio.DatagramTransport] = None
        self._client_addr = None
        self._remote: dict = {}
        self._lock = asyncio.Lock()
        self._peers = _LRUSet(1024)
        self._blocked_logged = _LRUSet(256)
        self._dns: dict = {}
        self._send_error: Optional[BaseException] = None
        self._tasks: set = set()
        self._closed = False
        self._loop = asyncio.get_running_loop()
        self._last = self._loop.time()
        self.up = 0
        self.down = 0

    # -- lifecycle ---------------------------------------------------------- #
    async def start(self) -> None:
        self._client_tr, _ = await self._loop.create_datagram_endpoint(
            lambda: _UdpProtocol(self._on_client_datagram),
            local_addr=(str(self.bind_ip), 0),
        )
        self.bind_port = self._client_tr.get_extra_info("sockname")[1]

    async def wait_idle(self) -> None:
        while True:
            remaining = self._last + self._srv.udp_idle_timeout - self._loop.time()
            if remaining <= 0:
                return
            await asyncio.sleep(remaining)

    async def aclose(self) -> None:
        if self._closed:
            return
        self._closed = True
        tasks = list(self._tasks)
        for t in tasks:
            t.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        transports = list(self._remote.values())
        if self._client_tr is not None:
            transports.append(self._client_tr)
        for tr in transports:
            tr.close()
        await asyncio.sleep(0)  # let the loop actually close the sockets
        await asyncio.sleep(0)

    def _touch(self) -> None:
        self._last = self._loop.time()

    def _spawn(self, coro) -> None:
        if len(self._tasks) >= self.MAX_PENDING:
            coro.close()
            return
        task = self._loop.create_task(coro)
        self._tasks.add(task)

        def _done(t):
            self._tasks.discard(t)
            if not t.cancelled() and t.exception() is not None:
                self._srv.log(f"{self._who} UDP internal error: {t.exception()!r}")

        task.add_done_callback(_done)

    # -- client -> remote --------------------------------------------------- #
    def _on_client_datagram(self, data: bytes, addr) -> None:
        if self._closed:
            return
        src = _parse_ip(addr[0])
        if src is None or _unmap(src) != self._client_ip:
            return
        if self._client_addr is None:
            self._client_addr = addr
        elif tuple(addr[:2]) != tuple(self._client_addr[:2]):
            return
        parsed = _parse_udp_header(data)
        if parsed is None:
            return
        host, ip, port, payload = parsed
        self._touch()
        if ip is not None:
            self._forward(_unmap(ip), port, payload)
        elif self._srv.block.is_name_blocked(host):
            self._log_blocked(host, port)
        else:
            self._spawn(self._resolve_and_forward(host, port, payload))

    async def _resolve_and_forward(self, host: str, port: int, payload: bytes) -> None:
        now = self._loop.time()
        hit = self._dns.get(host)
        if hit is not None and hit[0] > now:
            ips = hit[1]
        else:
            try:
                ips = (await self._srv.resolve_allowed(host, None))[:MAX_CONNECT_ATTEMPTS]
            except _Reject as rej:
                self._log_blocked(host, port, "BLOCKED" if rej.code == REP_NOT_ALLOWED
                                  else f"FAILED ({rej.detail})")
                return
            if len(self._dns) >= self.DNS_CACHE_MAX:
                self._dns.clear()
            self._dns[host] = (now + self.DNS_TTL, ips)
        # Use the first address the local stack accepts (e.g. skip IPv6 on a host
        # without IPv6) and remember it for the next datagrams.
        for ip in list(ips):
            if self._closed:
                return
            tr = self._remote.get(ip.version) or await self._ensure_remote(ip.version)
            if tr is None:
                continue
            if self._send(tr, ip, port, payload, host):
                if ips[0] != ip:
                    ips.remove(ip)
                    ips.insert(0, ip)
                return

    def _forward(self, ip, port: int, payload: bytes, host: Optional[str] = None) -> None:
        if self._closed:
            return
        if self._srv.block.is_ip_blocked(ip):
            self._log_blocked(host or str(ip), port)
            return
        tr = self._remote.get(ip.version)
        if tr is None:
            self._spawn(self._forward_slow(ip, port, payload, host))
        else:
            self._send(tr, ip, port, payload, host)

    async def _forward_slow(self, ip, port, payload, host) -> None:
        tr = await self._ensure_remote(ip.version)
        if tr is not None and not self._closed:
            self._send(tr, ip, port, payload, host)

    async def _ensure_remote(self, version: int):
        async with self._lock:
            if self._closed:
                return None
            tr = self._remote.get(version)
            if tr is None:
                try:
                    tr, _ = await self._loop.create_datagram_endpoint(
                        lambda: _UdpProtocol(self._on_remote_datagram, self._on_remote_error),
                        local_addr=("0.0.0.0" if version == 4 else "::", 0),
                    )
                except OSError:
                    return None
                if self._closed:
                    tr.close()
                    return None
                self._remote[version] = tr
            return tr

    def _send(self, tr, ip, port: int, payload: bytes, host: Optional[str]) -> bool:
        """Send one datagram; False if the local stack refused it right away."""
        self._send_error = None
        tr.sendto(payload, (str(ip), port))  # asyncio reports immediate errors via error_received
        if self._send_error is not None:
            return False
        if self._peers.add((ip, port)):
            target = _fmt_host(host, port) if host else _fmt_host(str(ip), port)
            self._srv.log(f"{self._who} UDP -> {target} ({_fmt_host(str(ip), port)})")
        self.up += len(payload)
        return True

    def _on_remote_error(self, exc: BaseException) -> None:
        self._send_error = exc

    def _log_blocked(self, host: str, port: int, tag: str = "BLOCKED") -> None:
        if self._blocked_logged.add((host, port, tag)):  # log each (destination, reason) once
            self._srv.log(f"{self._who} UDP -> {_fmt_host(host, port)} {tag}")

    # -- remote -> client --------------------------------------------------- #
    def _on_remote_datagram(self, data: bytes, addr) -> None:
        if self._closed or self._client_addr is None or self._client_tr is None:
            return
        ip = _parse_ip(addr[0])
        if ip is None:
            return
        ip = _unmap(ip)
        if (ip, addr[1]) not in self._peers:
            return
        packet = b"\x00\x00\x00" + _pack_addr(ip) + addr[1].to_bytes(2, "big") + data
        self._client_tr.sendto(packet, self._client_addr)
        self.down += len(data)
        self._touch()


async def _wait_eof(reader: asyncio.StreamReader) -> None:
    """Return when the TCP control connection ends (data on it is ignored)."""
    try:
        while await reader.read(1024):
            pass
    except (ConnectionError, OSError):
        pass


# --------------------------------------------------------------------------- #
# SOCKS5 server
# --------------------------------------------------------------------------- #
class Socks5Server(_Service):
    """Handle returned by :func:`serve_socks5`.

    ``await server.close()`` stops listening and gracefully tears down every
    active connection and UDP association.
    """

    def __init__(self, *, handshake_timeout, udp_idle_timeout, **kwargs):
        super().__init__(**kwargs)
        self.handshake_timeout = handshake_timeout
        self.udp_idle_timeout = udp_idle_timeout

    async def _reply(self, writer, rep: int, ip=None, port: int = 0) -> None:
        writer.write(_build_reply(rep, ip, port))
        await asyncio.wait_for(writer.drain(), self.handshake_timeout)

    async def _handle(self, reader, writer, who: str) -> None:
        try:
            request = await asyncio.wait_for(self._negotiate(reader, writer), self.handshake_timeout)
        except asyncio.TimeoutError:
            self.log(f"{who} handshake timed out")
            return
        if request is None:
            return
        cmd, host, ip, port = request
        if cmd == CMD_CONNECT:
            await self._connect(reader, writer, who, host, ip, port)
        else:
            await self._udp_associate(reader, writer, who)

    async def _negotiate(self, reader, writer):
        """Method selection + request parsing.  None => already answered/closed."""
        ver, nmethods = await reader.readexactly(2)
        if ver != SOCKS_VERSION:
            return None
        methods = await reader.readexactly(nmethods) if nmethods else b""
        if AUTH_NONE not in methods:
            writer.write(bytes([SOCKS_VERSION, AUTH_NO_ACCEPTABLE]))
            await writer.drain()
            return None
        writer.write(bytes([SOCKS_VERSION, AUTH_NONE]))
        await writer.drain()

        ver, cmd, _rsv, atyp = await reader.readexactly(4)
        if ver != SOCKS_VERSION:
            return None

        ip = None
        host: Optional[str] = None
        if atyp == ATYP_IPV4:
            ip = ipaddress.IPv4Address(await reader.readexactly(4))
            host = str(ip)
        elif atyp == ATYP_IPV6:
            ip = ipaddress.IPv6Address(await reader.readexactly(16))
            host = str(ip)
        elif atyp == ATYP_DOMAIN:
            n = (await reader.readexactly(1))[0]
            raw = await reader.readexactly(n) if n else b""
            try:
                host = raw.decode("utf-8")
            except UnicodeDecodeError:
                host = None
            if host is not None and not _is_safe_name(host):
                host = None  # empty, control characters or whitespace: not a host name
            if host is not None:
                ip = _parse_ip(host)  # IP literal sent as a domain name
        else:
            await self._reply(writer, REP_ATYP_NOT_SUPPORTED)
            return None
        port = int.from_bytes(await reader.readexactly(2), "big")

        if host is None:
            await self._reply(writer, REP_GENERAL_FAILURE)
            self.log(f"{_fmt_addr(writer.get_extra_info('peername'))} invalid destination name in request")
            return None
        if cmd not in (CMD_CONNECT, CMD_UDP_ASSOCIATE):  # incl. BIND
            await self._reply(writer, REP_COMMAND_NOT_SUPPORTED)
            self.log(f"{_fmt_addr(writer.get_extra_info('peername'))} command 0x{cmd:02x} not supported")
            return None
        return cmd, host, ip, port

    # -- CONNECT ------------------------------------------------------------ #
    async def _connect(self, reader, writer, who: str, host: str, ip, port: int) -> None:
        target = _fmt_host(host, port)
        try:
            addresses = await self.resolve_allowed(host, ip)
        except _Reject as rej:
            await self._reply(writer, rej.code)
            tag = "BLOCKED" if rej.code == REP_NOT_ALLOWED else "FAILED"
            self.log(f"{who} CONNECT {target} {tag} (rep={rej.code}: {rej.detail})")
            return

        try:
            up_reader, up_writer = await self._open_upstream(addresses, port)
        except (OSError, asyncio.TimeoutError) as exc:
            rep = _reply_code_for(exc)
            await self._reply(writer, rep)
            self.log(f"{who} CONNECT {target} FAILED (rep={rep}: {_describe(exc)})")
            return

        started = time.monotonic()
        try:
            _tune_socket(up_writer)
            sockname = up_writer.get_extra_info("sockname")
            bind_ip = _unmap(_parse_ip(sockname[0])) if sockname else None
            await self._reply(writer, REP_SUCCEEDED, bind_ip, sockname[1] if sockname else 0)
            peer_ip = up_writer.get_extra_info("peername")[0]
            self.log(f"{who} CONNECT {target} OK ({_fmt_host(str(peer_ip), port)})")
            sent, received, reason = await self._relay(reader, writer, up_reader, up_writer)
            self.log(f"{who} CLOSED {target} up={sent}B down={received}B "
                     f"{time.monotonic() - started:.1f}s ({reason})")
        finally:
            await _close_writer(up_writer, self.close_timeout)

    # -- UDP ASSOCIATE ------------------------------------------------------ #
    async def _udp_associate(self, reader, writer, who: str) -> None:
        sockname = writer.get_extra_info("sockname")
        peername = writer.get_extra_info("peername")
        local_ip = _parse_ip(sockname[0]) if sockname else None
        client_ip = _parse_ip(peername[0]) if peername else None
        if local_ip is None or client_ip is None:
            await self._reply(writer, REP_GENERAL_FAILURE)
            return
        relay = _UdpRelay(self, who, _unmap(client_ip), _unmap(local_ip))
        try:
            await relay.start()
        except OSError as exc:
            rep = _reply_code_for(exc)
            await self._reply(writer, rep)
            self.log(f"{who} UDP ASSOCIATE FAILED (rep={rep}: {_describe(exc)})")
            return

        started = time.monotonic()
        try:
            await self._reply(writer, REP_SUCCEEDED, relay.bind_ip, relay.bind_port)
            self.log(f"{who} UDP ASSOCIATE OK (relay {_fmt_host(str(relay.bind_ip), relay.bind_port)})")
            loop = asyncio.get_running_loop()
            eof = loop.create_task(_wait_eof(reader))
            idle = loop.create_task(relay.wait_idle())
            try:
                done, _ = await asyncio.wait({eof, idle}, return_when=asyncio.FIRST_COMPLETED)
            finally:
                eof.cancel()
                idle.cancel()
                await asyncio.gather(eof, idle, return_exceptions=True)
            reason = "control connection closed" if eof in done else "idle timeout"
            self.log(f"{who} UDP CLOSED up={relay.up}B down={relay.down}B "
                     f"{time.monotonic() - started:.1f}s ({reason})")
        finally:
            await relay.aclose()


# --------------------------------------------------------------------------- #
# TCP port forwarder
# --------------------------------------------------------------------------- #
class TcpForwarder(_Service):
    """Handle returned by :func:`forward_tcp`."""

    def __init__(self, *, target_host: str, target_port: int, **kwargs):
        super().__init__(**kwargs)
        self._host = target_host
        self._ip = _parse_ip(target_host)
        self._port = target_port

    async def _handle(self, reader, writer, who: str) -> None:
        target = _fmt_host(self._host, self._port)
        try:
            addresses = await self.resolve_allowed(self._host, self._ip)
        except _Reject as rej:
            self.log(f"{who} -> {target} REFUSED ({rej.detail})")
            return
        try:
            up_reader, up_writer = await self._open_upstream(addresses, self._port)
        except (OSError, asyncio.TimeoutError) as exc:
            self.log(f"{who} -> {target} FAILED ({_describe(exc)})")
            return

        started = time.monotonic()
        try:
            _tune_socket(up_writer)
            peer_ip = up_writer.get_extra_info("peername")[0]
            self.log(f"{who} -> {target} OK ({_fmt_host(str(peer_ip), self._port)})")
            sent, received, reason = await self._relay(reader, writer, up_reader, up_writer)
            self.log(f"{who} CLOSED {target} up={sent}B down={received}B "
                     f"{time.monotonic() - started:.1f}s ({reason})")
        finally:
            await _close_writer(up_writer, self.close_timeout)


# --------------------------------------------------------------------------- #
# UDP port forwarder
# --------------------------------------------------------------------------- #
class _UdpSession:
    __slots__ = ("key", "client_addr", "transport", "backlog", "last", "started", "up", "down")

    def __init__(self, key, client_addr, now: float):
        self.key = key
        self.client_addr = client_addr
        self.transport: Optional[asyncio.DatagramTransport] = None
        self.backlog: List[bytes] = []   # datagrams that arrived while the session was opening
        self.last = now
        self.started = now
        self.up = 0
        self.down = 0


class _UdpFrontend(_Service):
    """Common part of the UDP forwarders: the listening socket and the session table."""

    def __init__(self, *, max_sessions: int, **kwargs):
        super().__init__(**kwargs)
        self.max_sessions = max_sessions
        self._listener: Optional[asyncio.DatagramTransport] = None
        self._sessions: dict = {}
        self._closed = False
        self._limit_logged = float("-inf")

    @property
    def sockets(self):
        if self._listener is None:
            return ()
        sock = self._listener.get_extra_info("socket")
        return (sock,) if sock is not None else ()

    async def _bind_udp(self, addr: Optional[str], port: int, what: str) -> None:
        loop = asyncio.get_running_loop()
        self._listener, _ = await loop.create_datagram_endpoint(
            lambda: _UdpProtocol(self._on_datagram), local_addr=(addr or "0.0.0.0", port))
        self.log(f"{what} listening on {_fmt_addr(self._listener.get_extra_info('sockname'))}")

    def _on_datagram(self, data: bytes, addr) -> None:
        raise NotImplementedError

    def _drop_all_sessions(self) -> None:
        """Hook: synchronously release sessions that are not owned by a task."""

    def _at_session_limit(self, loop) -> bool:
        if len(self._sessions) < self.max_sessions:
            return False
        now = loop.time()
        if now - self._limit_logged > 10:  # do not flood the log
            self._limit_logged = now
            self.log(f"UDP session limit ({self.max_sessions}) reached, dropping new clients")
        return True

    def _spawn(self, coro) -> None:
        task = asyncio.get_running_loop().create_task(coro)
        self._tasks.add(task)

        def _done(t):
            self._tasks.discard(t)
            if not t.cancelled() and t.exception() is not None:
                self.log(f"internal error: {t.exception()!r}")

        task.add_done_callback(_done)

    async def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        tasks = list(self._tasks)
        for t in tasks:
            t.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        self._drop_all_sessions()
        if self._listener is not None:
            self._listener.close()
        await asyncio.sleep(0)  # let the loop actually close the sockets
        await asyncio.sleep(0)


class UdpForwarder(_UdpFrontend):
    """Handle returned by :func:`forward_udp`.

    Every client address gets its own *connected* upstream socket, so the kernel
    only delivers datagrams coming from the target and replies can be routed
    back to the right client.  Sessions are closed after ``idle_timeout``
    seconds without traffic in either direction.
    """

    BACKLOG_MAX = 32          # datagrams buffered while a session is being opened
    TARGET_TTL = 30.0         # how long a successful target resolution is cached
    TARGET_FAIL_TTL = 5.0     # ... and a failed one (also throttles log spam)

    def __init__(self, *, target_host: str, target_port: int, **kwargs):
        super().__init__(**kwargs)
        self._host = target_host
        self._ip = _parse_ip(target_host)
        self._port = target_port
        self._reaper: Optional[asyncio.Task] = None
        self._target_cache = None
        self._resolve_lock = asyncio.Lock()

    async def _start(self, addr: Optional[str], port: int) -> None:
        await self._bind_udp(addr, port, "UDP forwarder")
        self._spawn(self._reap())

    def _drop_all_sessions(self) -> None:
        for session in list(self._sessions.values()):
            self._drop_session(session, "server closing")

    # -- target resolution (cached) ----------------------------------------- #
    async def _resolve_target(self):
        loop = asyncio.get_running_loop()
        async with self._resolve_lock:
            cached = self._target_cache
            if cached is not None and cached[0] > loop.time():
                if cached[1] is None:
                    raise _Reject(cached[2], cached[3])
                return cached[1]
            try:
                addresses = (await self.resolve_allowed(self._host, self._ip))[:MAX_CONNECT_ATTEMPTS]
            except _Reject as rej:
                self._target_cache = (loop.time() + self.TARGET_FAIL_TTL, None, rej.code, rej.detail)
                self.log(f"UDP target {_fmt_host(self._host, self._port)} REFUSED ({rej.detail})")
                raise
            self._target_cache = (loop.time() + self.TARGET_TTL, addresses, 0, "")
            return addresses

    # -- client -> target --------------------------------------------------- #
    def _on_datagram(self, data: bytes, addr) -> None:
        if self._closed:
            return
        loop = asyncio.get_running_loop()
        key = (addr[0], addr[1])
        session = self._sessions.get(key)
        if session is None:
            if self._at_session_limit(loop):
                return
            session = _UdpSession(key, addr, loop.time())
            session.backlog.append(data)
            self._sessions[key] = session
            self._spawn(self._open_session(session))
            return
        session.last = loop.time()
        if session.transport is None:  # still opening
            if len(session.backlog) < self.BACKLOG_MAX:
                session.backlog.append(data)
            return
        session.transport.sendto(data)
        session.up += len(data)

    async def _open_session(self, session: _UdpSession) -> None:
        loop = asyncio.get_running_loop()
        who = _fmt_addr(session.client_addr)
        target = _fmt_host(self._host, self._port)
        transport = None
        committed = False  # True once the session owns the transport and is usable
        try:
            addresses = await self._resolve_target()
            last_exc: BaseException = OSError("no address to connect to")
            for ip in list(addresses):  # first address the local stack accepts (connect() fails fast)
                try:
                    transport, _ = await loop.create_datagram_endpoint(
                        lambda: _UdpProtocol(lambda data, _addr: self._on_upstream(session, data)),
                        remote_addr=(str(ip), self._port),
                    )
                    break
                except OSError as exc:
                    last_exc = exc
            if transport is None:
                raise last_exc
            if addresses[0] != ip:  # remember what works for the next sessions
                addresses.remove(ip)
                addresses.insert(0, ip)
            if self._closed or self._sessions.get(session.key) is not session:
                return  # closed meanwhile; the finally clause releases the socket
            session.transport = transport
            committed = True
            self.log(f"{who} UDP -> {target} OK ({_fmt_host(str(ip), self._port)})")
            for data in session.backlog:
                transport.sendto(data)
                session.up += len(data)
            session.backlog.clear()
        except asyncio.CancelledError:
            raise
        except _Reject:
            pass  # already logged by _resolve_target
        except Exception as exc:  # OSError, or anything unexpected
            self.log(f"{who} UDP -> {target} FAILED ({_describe(exc)})")
        finally:
            if not committed:  # whatever went wrong: no half-open session, no leaked socket
                if transport is not None:
                    transport.close()
                if self._sessions.get(session.key) is session:
                    del self._sessions[session.key]

    # -- target -> client --------------------------------------------------- #
    def _on_upstream(self, session: _UdpSession, data: bytes) -> None:
        if self._closed or self._listener is None:
            return
        session.last = asyncio.get_running_loop().time()
        session.down += len(data)
        self._listener.sendto(data, session.client_addr)

    # -- idle sessions ------------------------------------------------------ #
    def _drop_session(self, session: _UdpSession, reason: str) -> None:
        if self._sessions.get(session.key) is session:
            del self._sessions[session.key]
        if session.transport is not None:
            session.transport.close()
            session.transport = None
            elapsed = asyncio.get_running_loop().time() - session.started
            self.log(f"{_fmt_addr(session.client_addr)} UDP CLOSED "
                     f"{_fmt_host(self._host, self._port)} up={session.up}B "
                     f"down={session.down}B {elapsed:.1f}s ({reason})")

    async def _reap(self) -> None:
        loop = asyncio.get_running_loop()
        interval = min(5.0, max(0.1, self.idle_timeout / 4))
        while True:
            await asyncio.sleep(interval)
            try:
                now = loop.time()
                for session in [s for s in self._sessions.values()
                                if s.transport is not None and now - s.last >= self.idle_timeout]:
                    self._drop_session(session, "idle timeout")
            except Exception as exc:  # a dead reaper would leak sessions forever
                self.log(f"internal error while expiring sessions: {exc!r}")


# --------------------------------------------------------------------------- #
# Forwarders that tunnel through an upstream SOCKS5 server (SOCKS5 *client*)
# --------------------------------------------------------------------------- #
AUTH_USERPASS = 0x02

_REP_TEXT = {
    REP_GENERAL_FAILURE: "general SOCKS server failure",
    REP_NOT_ALLOWED: "connection not allowed by ruleset",
    REP_NETWORK_UNREACHABLE: "network unreachable",
    REP_HOST_UNREACHABLE: "host unreachable",
    REP_CONNECTION_REFUSED: "connection refused",
    REP_TTL_EXPIRED: "TTL expired",
    REP_COMMAND_NOT_SUPPORTED: "command not supported",
    REP_ATYP_NOT_SUPPORTED: "address type not supported",
}


class _SocksError(Exception):
    """The upstream SOCKS5 server refused the request or misbehaved."""

    def __init__(self, message: str, rep: Optional[int] = None):
        super().__init__(message)
        self.rep = rep


def _encode_address(host: str) -> bytes:
    """ATYP + address as used in SOCKS5 requests (names are sent unresolved)."""
    ip = _parse_ip(host)
    if ip is not None:
        return _pack_addr(ip)
    try:
        raw = host.encode("ascii") if host.isascii() else host.encode("idna")
    except UnicodeError:
        raise ValueError(f"invalid host name: {host!r}")
    if not 0 < len(raw) < 256:
        raise ValueError(f"host name must be 1-255 bytes long: {host!r}")
    return bytes([ATYP_DOMAIN, len(raw)]) + raw


def _check_credentials(username: Optional[str], password: Optional[str]) -> None:
    if (username is None) != (password is None):
        raise ValueError("username and password must be given together")
    for value in (username, password):
        if value is not None and not 0 < len(value.encode("utf-8")) < 256:
            raise ValueError("username and password must be 1-255 bytes long")


async def _socks5_request(reader, writer, cmd: int, host: str, port: int,
                          username: Optional[str], password: Optional[str]):
    """Run the SOCKS5 client handshake; return the reply's (BND.ADDR, BND.PORT).

    Raises _SocksError when the server refuses.  The caller applies the timeout.
    """
    methods = [AUTH_NONE] + ([AUTH_USERPASS] if username is not None else [])
    writer.write(bytes([SOCKS_VERSION, len(methods)] + methods))
    await writer.drain()
    ver, method = await reader.readexactly(2)
    if ver != SOCKS_VERSION:
        raise _SocksError("upstream server is not a SOCKS5 server")
    if method == AUTH_NO_ACCEPTABLE:
        raise _SocksError("upstream server accepts none of our authentication methods")
    if method == AUTH_USERPASS and username is not None:
        user, pwd = username.encode("utf-8"), password.encode("utf-8")
        writer.write(bytes([1, len(user)]) + user + bytes([len(pwd)]) + pwd)
        await writer.drain()
        _ver, status = await reader.readexactly(2)
        if status != 0:
            raise _SocksError("upstream server rejected the username/password")
    elif method != AUTH_NONE:
        raise _SocksError(f"upstream server chose unsupported method 0x{method:02x}")

    writer.write(bytes([SOCKS_VERSION, cmd, 0x00]) + _encode_address(host) + port.to_bytes(2, "big"))
    await writer.drain()
    ver, rep, _rsv, atyp = await reader.readexactly(4)
    if ver != SOCKS_VERSION:
        raise _SocksError("malformed reply from upstream server")
    if atyp == ATYP_IPV4:
        bnd_host = str(ipaddress.IPv4Address(await reader.readexactly(4)))
    elif atyp == ATYP_IPV6:
        bnd_host = str(ipaddress.IPv6Address(await reader.readexactly(16)))
    elif atyp == ATYP_DOMAIN:
        n = (await reader.readexactly(1))[0]
        bnd_host = (await reader.readexactly(n)).decode("utf-8", "replace")
    else:
        raise _SocksError("malformed reply from upstream server (address type)")
    bnd_port = int.from_bytes(await reader.readexactly(2), "big")
    if rep != REP_SUCCEEDED:
        raise _SocksError(f"{_REP_TEXT.get(rep, 'unknown error')} (reply 0x{rep:02x})", rep)
    return bnd_host, bnd_port


class TcpForwarderViaSocks5(_Service):
    """Handle returned by :func:`forward_tcp_via_socks5`."""

    def __init__(self, *, socks_host: str, socks_port: int, target_host: str, target_port: int,
                 username: Optional[str], password: Optional[str], handshake_timeout: float,
                 **kwargs):
        super().__init__(**kwargs)
        self._socks_host = socks_host
        self._socks_port = socks_port
        self._host = target_host
        self._port = target_port
        self._username = username
        self._password = password
        self.handshake_timeout = handshake_timeout

    async def _handle(self, reader, writer, who: str) -> None:
        target = _fmt_host(self._host, self._port)
        via = _fmt_host(self._socks_host, self._socks_port)
        try:
            up_reader, up_writer = await asyncio.wait_for(
                asyncio.open_connection(self._socks_host, self._socks_port, happy_eyeballs_delay=0.25), self.connect_timeout)
        except (OSError, asyncio.TimeoutError) as exc:
            self.log(f"{who} -> {target} via {via} FAILED (cannot reach SOCKS5 server: {_describe(exc)})")
            return

        started = time.monotonic()
        try:
            _tune_socket(up_writer)
            try:
                await asyncio.wait_for(
                    _socks5_request(up_reader, up_writer, CMD_CONNECT, self._host, self._port,
                                    self._username, self._password),
                    self.handshake_timeout)
            except _SocksError as exc:
                self.log(f"{who} -> {target} via {via} FAILED ({exc})")
                return
            except (OSError, asyncio.TimeoutError, asyncio.IncompleteReadError) as exc:
                self.log(f"{who} -> {target} via {via} FAILED (SOCKS5 handshake: {_describe(exc)})")
                return
            self.log(f"{who} -> {target} via {via} OK")
            sent, received, reason = await self._relay(reader, writer, up_reader, up_writer)
            self.log(f"{who} CLOSED {target} up={sent}B down={received}B "
                     f"{time.monotonic() - started:.1f}s ({reason})")
        finally:
            await _close_writer(up_writer, self.close_timeout)


class _ViaSession:
    __slots__ = ("key", "client_addr", "transport", "relay", "relay_ip", "ctrl_reader",
                 "ctrl_writer", "backlog", "last", "started", "up", "down")

    def __init__(self, key, client_addr, now: float):
        self.key = key
        self.client_addr = client_addr
        self.transport: Optional[asyncio.DatagramTransport] = None
        self.relay = None            # (ip string, port) of the proxy's UDP relay
        self.relay_ip = None
        self.ctrl_reader = None
        self.ctrl_writer = None
        self.backlog: List[bytes] = []   # datagrams that arrived while the session was opening
        self.last = now
        self.started = now
        self.up = 0
        self.down = 0


class UdpForwarderViaSocks5(_UdpFrontend):
    """Handle returned by :func:`forward_udp_via_socks5`.

    Every local client address gets its own SOCKS5 UDP association (a TCP
    control connection plus a UDP socket), so that replies from the target can
    be routed back to the right client.  Each session is run by one task, which
    also releases its sockets.
    """

    BACKLOG_MAX = 32

    def __init__(self, *, socks_host: str, socks_port: int, target_host: str, target_port: int,
                 username: Optional[str], password: Optional[str], handshake_timeout: float,
                 connect_timeout: float, use_server_address: bool, **kwargs):
        super().__init__(connect_timeout=connect_timeout, **kwargs)
        self._socks_host = socks_host
        self._socks_port = socks_port
        self._host = target_host
        self._port = target_port
        self._username = username
        self._password = password
        self.handshake_timeout = handshake_timeout
        self._use_server_address = use_server_address
        # SOCKS5 UDP request header for our (constant) target
        self._udp_header = b"\x00\x00\x00" + _encode_address(target_host) + target_port.to_bytes(2, "big")

    async def _start(self, addr: Optional[str], port: int) -> None:
        await self._bind_udp(addr, port, "UDP forwarder via SOCKS5")

    # -- local client -> proxy ---------------------------------------------- #
    def _on_datagram(self, data: bytes, addr) -> None:
        if self._closed:
            return
        loop = asyncio.get_running_loop()
        key = (addr[0], addr[1])
        session = self._sessions.get(key)
        if session is None:
            if self._at_session_limit(loop):
                return
            session = _ViaSession(key, addr, loop.time())
            session.backlog.append(data)
            self._sessions[key] = session
            self._spawn(self._run_session(session))
            return
        session.last = loop.time()
        if session.transport is None:  # still opening
            if len(session.backlog) < self.BACKLOG_MAX:
                session.backlog.append(data)
            return
        session.transport.sendto(self._udp_header + data, session.relay)
        session.up += len(data)

    # -- proxy -> local client ---------------------------------------------- #
    def _on_relay_datagram(self, session: _ViaSession, data: bytes, addr) -> None:
        if self._closed or self._listener is None or session.transport is None:
            return
        src = _parse_ip(addr[0])
        if src is None or _unmap(src) != session.relay_ip:  # only the proxy may talk to us
            return
        parsed = _parse_udp_header(data)
        if parsed is None:
            return
        payload = parsed[3]
        session.last = asyncio.get_running_loop().time()
        session.down += len(payload)
        self._listener.sendto(payload, session.client_addr)

    # -- session life cycle ------------------------------------------------- #
    async def _open(self, session: _ViaSession) -> None:
        loop = asyncio.get_running_loop()
        session.ctrl_reader, session.ctrl_writer = await asyncio.wait_for(
            asyncio.open_connection(self._socks_host, self._socks_port, happy_eyeballs_delay=0.25), self.connect_timeout)
        _tune_socket(session.ctrl_writer)
        # DST.ADDR/PORT 0.0.0.0:0: "I do not know from where I will send" (widely accepted)
        bnd_host, bnd_port = await asyncio.wait_for(
            _socks5_request(session.ctrl_reader, session.ctrl_writer, CMD_UDP_ASSOCIATE,
                            "0.0.0.0", 0, self._username, self._password),
            self.handshake_timeout)
        peer = session.ctrl_writer.get_extra_info("peername")
        server_ip = _unmap(_parse_ip(peer[0]))
        relay_ip = _parse_ip(bnd_host)  # None if the server announced a domain name
        if self._use_server_address or relay_ip is None or relay_ip.is_unspecified:
            relay_ip = server_ip       # "0.0.0.0" means: the address you already talk to
        else:
            relay_ip = _unmap(relay_ip)
        if not 0 < bnd_port < 65536:
            raise _SocksError("upstream server announced an invalid UDP relay port")
        session.relay_ip = relay_ip
        session.relay = (str(relay_ip), bnd_port)
        session.transport, _ = await loop.create_datagram_endpoint(
            lambda: _UdpProtocol(lambda d, a: self._on_relay_datagram(session, d, a)),
            local_addr=("0.0.0.0" if relay_ip.version == 4 else "::", 0),
        )

    async def _wait_idle(self, session: _ViaSession) -> None:
        loop = asyncio.get_running_loop()
        while True:
            remaining = session.last + self.idle_timeout - loop.time()
            if remaining <= 0:
                return
            await asyncio.sleep(remaining)

    async def _run_session(self, session: _ViaSession) -> None:
        loop = asyncio.get_running_loop()
        who = _fmt_addr(session.client_addr)
        target = _fmt_host(self._host, self._port)
        via = _fmt_host(self._socks_host, self._socks_port)
        opened = False
        reason = "closed"
        try:
            await self._open(session)
            opened = True
            self.log(f"{who} UDP -> {target} via {via} OK (relay {_fmt_host(*session.relay)})")
            for data in session.backlog:
                session.transport.sendto(self._udp_header + data, session.relay)
                session.up += len(data)
            session.backlog.clear()
            eof = loop.create_task(_wait_eof(session.ctrl_reader))
            idle = loop.create_task(self._wait_idle(session))
            try:
                done, _ = await asyncio.wait({eof, idle}, return_when=asyncio.FIRST_COMPLETED)
            finally:
                eof.cancel()
                idle.cancel()
                await asyncio.gather(eof, idle, return_exceptions=True)
            reason = "SOCKS5 control connection closed" if eof in done else "idle timeout"
        except asyncio.CancelledError:
            reason = "server closing"
            raise
        except _SocksError as exc:
            self.log(f"{who} UDP -> {target} via {via} FAILED ({exc})")
        except (OSError, asyncio.TimeoutError, asyncio.IncompleteReadError) as exc:
            self.log(f"{who} UDP -> {target} via {via} FAILED ({_describe(exc)})")
        except Exception as exc:
            self.log(f"{who} UDP -> {target} via {via} internal error: {exc!r}")
        finally:
            if self._sessions.get(session.key) is session:
                del self._sessions[session.key]
            transport, session.transport = session.transport, None
            if transport is not None:
                transport.close()
            await _close_writer(session.ctrl_writer, self.close_timeout)
            if opened:
                self.log(f"{who} UDP CLOSED {target} via {via} up={session.up}B "
                         f"down={session.down}B {loop.time() - session.started:.1f}s ({reason})")


# --------------------------------------------------------------------------- #
# Public entry points
# --------------------------------------------------------------------------- #
async def serve_socks5(
    addr: Optional[str] = "127.0.0.1",
    port: int = 1080,
    *,
    verbose: bool = False,
    block_list: Optional[Iterable] = None,
    handshake_timeout: float = 10.0,
    connect_timeout: float = 15.0,
    dns_timeout: float = 10.0,
    idle_timeout: float = 300.0,
    udp_idle_timeout: float = 60.0,
    close_timeout: float = 5.0,
    max_connections: int = 1024,
    backlog: int = 128,
    resolver: Optional[Resolver] = None,
) -> Socks5Server:
    """Start a SOCKS5 server and return immediately (it keeps running on the loop).

    Parameters
    ----------
    addr, port:
        Where to listen.  ``addr=None`` (or "") listens on all interfaces.
    verbose:
        Print who connects to where (and when it ends) to stdout.
    block_list:
        Destinations that are refused (reply code 0x02).  Entries may be CIDR
        strings / IPs (``"10.0.0.0/8"``, ``"::1"``), ``ipaddress`` objects, or
        host names (``"example.com"`` also blocks ``*.example.com``).
        ``None`` (default) uses ``DEFAULT_BLOCK_LIST`` (loopback etc.); pass
        ``()`` to block nothing, or ``DEFAULT_BLOCK_LIST + (...)`` to extend it.
    handshake_timeout:
        Seconds the client has to finish the SOCKS handshake.
    connect_timeout:
        Seconds allowed for each outgoing TCP connect attempt.
    dns_timeout:
        Seconds allowed for resolving a destination name.
    idle_timeout:
        A relayed TCP connection with no traffic in either direction for this
        long (or whose peer stops reading for this long) is torn down.
    udp_idle_timeout:
        A UDP association without datagrams (in either direction, to any
        destination) for this long is closed.
    close_timeout:
        Seconds to wait for a graceful close before the socket is aborted.
    max_connections:
        Maximum simultaneous client connections; extra ones are closed at once.
        Keep it well below ``ulimit -n`` (a UDP association uses up to 3
        extra descriptors).
    resolver:
        Optional ``async def resolver(host) -> list_of_ip_strings`` replacing
        the default ``loop.getaddrinfo`` based lookup.  Error contract: raise
        ``OSError`` (e.g. ``socket.gaierror``) or ``asyncio.TimeoutError`` when
        the name cannot be resolved (reply 0x04, host unreachable); any other
        exception, or a result that is not an iterable of IP addresses, is
        treated as a resolver bug (reply 0x01, general failure) and logged.
        An empty result means "no such host" (0x04).  The lookup is also cut
        off after ``dns_timeout`` seconds.

    Returns
    -------
    Socks5Server
        ``await server.close()`` shuts everything down gracefully.
    """
    srv = Socks5Server(
        verbose=verbose, block_list=block_list, handshake_timeout=handshake_timeout,
        connect_timeout=connect_timeout, dns_timeout=dns_timeout, idle_timeout=idle_timeout,
        udp_idle_timeout=udp_idle_timeout, close_timeout=close_timeout,
        max_connections=max_connections, resolver=resolver,
    )
    await srv._listen(addr, port, backlog, "SOCKS5 server")
    return srv


async def forward_tcp(
    listen_addr: Optional[str],
    listen_port: int,
    target_host: str,
    target_port: int,
    *,
    verbose: bool = False,
    block_list: Optional[Iterable] = (),
    connect_timeout: float = 15.0,
    dns_timeout: float = 10.0,
    idle_timeout: float = 300.0,
    close_timeout: float = 5.0,
    max_connections: int = 1024,
    backlog: int = 128,
    resolver: Optional[Resolver] = None,
) -> TcpForwarder:
    """Listen on ``listen_addr:listen_port`` and relay every TCP connection to
    ``target_host:target_port``.  Returns immediately; the forwarder keeps
    running on the event loop.

    The target name is resolved for every connection (so DNS changes are
    picked up) and the resolved addresses are tried in turn.  If the target
    cannot be reached the client connection is simply closed.

    ``block_list`` defaults to ``()`` (nothing blocked, since the operator chose
    the target); pass a list, or ``None`` for the loopback default, if the
    target is a host name whose resolution you do not fully trust.
    The other parameters mean the same as in :func:`serve_socks5`.

    Returns
    -------
    TcpForwarder
        ``await forwarder.close()`` shuts everything down gracefully.
    """
    host, port = _check_target(target_host, target_port)
    fwd = TcpForwarder(
        target_host=host, target_port=port, verbose=verbose, block_list=block_list,
        connect_timeout=connect_timeout, dns_timeout=dns_timeout, idle_timeout=idle_timeout,
        close_timeout=close_timeout, max_connections=max_connections, resolver=resolver,
    )
    await fwd._listen(listen_addr, listen_port, backlog,
                      f"TCP forwarder (-> {_fmt_host(host, port)})")
    return fwd


async def forward_udp(
    listen_addr: Optional[str],
    listen_port: int,
    target_host: str,
    target_port: int,
    *,
    verbose: bool = False,
    block_list: Optional[Iterable] = (),
    idle_timeout: float = 60.0,
    dns_timeout: float = 10.0,
    close_timeout: float = 5.0,
    max_sessions: int = 1024,
    resolver: Optional[Resolver] = None,
) -> UdpForwarder:
    """Listen for UDP datagrams on ``listen_addr:listen_port`` and forward them
    to ``target_host:target_port``.  Returns immediately; the forwarder keeps
    running on the event loop.

    Each client address (ip, port) gets its own upstream socket, a "session",
    which is how replies find their way back.  A session is closed after
    ``idle_timeout`` seconds without traffic in either direction.  When
    ``max_sessions`` sessions exist, datagrams from new clients are dropped
    until old sessions expire.  The target resolution is cached for a short
    time.  ``listen_addr=None`` listens on IPv4 only (``"0.0.0.0"``); pass
    ``"::"`` for IPv6.

    ``block_list`` defaults to ``()`` (nothing blocked); see :func:`forward_tcp`.

    Returns
    -------
    UdpForwarder
        ``await forwarder.close()`` shuts everything down gracefully.
    """
    host, port = _check_target(target_host, target_port)
    fwd = UdpForwarder(
        target_host=host, target_port=port, max_sessions=max_sessions, verbose=verbose,
        block_list=block_list, dns_timeout=dns_timeout, idle_timeout=idle_timeout,
        close_timeout=close_timeout, resolver=resolver,
    )
    await fwd._start(listen_addr, listen_port)
    return fwd


async def forward_tcp_via_socks5(
    listen_addr: Optional[str],
    listen_port: int,
    socks_host: str,
    socks_port: int,
    target_host: str,
    target_port: int,
    *,
    username: Optional[str] = None,
    password: Optional[str] = None,
    verbose: bool = False,
    connect_timeout: float = 15.0,
    handshake_timeout: float = 10.0,
    idle_timeout: float = 300.0,
    close_timeout: float = 5.0,
    max_connections: int = 1024,
    backlog: int = 128,
) -> TcpForwarderViaSocks5:
    """Listen on ``listen_addr:listen_port``; relay every TCP connection to
    ``target_host:target_port`` *through* the SOCKS5 server at
    ``socks_host:socks_port``.  Returns immediately; the forwarder keeps running
    on the event loop.

    This lets an application that cannot speak SOCKS5 reach a target that only
    the SOCKS5 server can reach: point the application at the listen address.

    The target name is sent to the SOCKS5 server unresolved (the server does the
    DNS lookup, which matters when the name only resolves on its side); an IP
    literal is sent as an address.  If the SOCKS5 server cannot be reached,
    refuses the request, or fails the handshake, the local client connection is
    closed (a plain TCP client cannot be told why); the reason is logged when
    ``verbose`` is set.

    Parameters
    ----------
    username, password:
        Credentials for the SOCKS5 server (RFC 1929); both or neither.
        Without them only "no authentication" is offered.
    connect_timeout:
        Seconds allowed for reaching the SOCKS5 server (name resolution of
        ``socks_host`` included).
    handshake_timeout:
        Seconds allowed for the whole SOCKS5 negotiation, including the time the
        server needs to connect to the target.
    idle_timeout, close_timeout, max_connections, backlog:
        As in :func:`serve_socks5`.

    Returns
    -------
    TcpForwarderViaSocks5
        ``await forwarder.close()`` shuts everything down gracefully.
    """
    shost, sport = _check_target(socks_host, socks_port)
    thost, tport = _check_target(target_host, target_port)
    _encode_address(thost)  # validate early
    _check_credentials(username, password)
    fwd = TcpForwarderViaSocks5(
        socks_host=shost, socks_port=sport, target_host=thost, target_port=tport,
        username=username, password=password, handshake_timeout=handshake_timeout,
        verbose=verbose, block_list=(), dns_timeout=10.0, idle_timeout=idle_timeout,
        close_timeout=close_timeout, resolver=None, connect_timeout=connect_timeout,
        max_connections=max_connections,
    )
    await fwd._listen(listen_addr, listen_port, backlog,
                      f"TCP forwarder (-> {_fmt_host(thost, tport)} via SOCKS5 {_fmt_host(shost, sport)})")
    return fwd


async def forward_udp_via_socks5(
    listen_addr: Optional[str],
    listen_port: int,
    socks_host: str,
    socks_port: int,
    target_host: str,
    target_port: int,
    *,
    username: Optional[str] = None,
    password: Optional[str] = None,
    verbose: bool = False,
    use_server_address: bool = False,
    connect_timeout: float = 15.0,
    handshake_timeout: float = 10.0,
    idle_timeout: float = 60.0,
    close_timeout: float = 5.0,
    max_sessions: int = 1024,
) -> UdpForwarderViaSocks5:
    """Listen for UDP datagrams on ``listen_addr:listen_port`` and forward them
    to ``target_host:target_port`` *through* the SOCKS5 server at
    ``socks_host:socks_port`` (UDP ASSOCIATE).  Returns immediately; the
    forwarder keeps running on the event loop.

    Each local client address (ip, port) gets its own session: a TCP control
    connection and a UDP socket towards the proxy's UDP relay.  (A shared
    association could not tell the clients' replies apart, since they all come
    from the same target.)  A session ends when the SOCKS5 control connection
    closes, after ``idle_timeout`` seconds without traffic in either direction,
    or when the forwarder is closed.  The next datagram of that client then
    opens a new session.  If the SOCKS5 server cannot be reached or refuses, the
    client's datagrams are dropped and the reason is logged when ``verbose``.
    When ``max_sessions`` sessions exist, datagrams from new clients are dropped
    until old sessions end.  Each session uses 2 file descriptors.

    Parameters
    ----------
    use_server_address:
        The UDP relay address in the proxy's reply is used, except when it is
        unspecified (0.0.0.0 / ::), in which case the address of the SOCKS5
        server itself is used.  Set this to always use the SOCKS5 server's
        address (and only the announced port), e.g. when the server sits behind
        NAT or in a container and announces an address you cannot reach.
    username, password, connect_timeout, handshake_timeout, close_timeout:
        As in :func:`forward_tcp_via_socks5`.
    idle_timeout:
        Per-session idle timeout.
    listen_addr:
        ``None`` listens on IPv4 only (``"0.0.0.0"``); pass ``"::"`` for IPv6.

    Returns
    -------
    UdpForwarderViaSocks5
        ``await forwarder.close()`` shuts everything down gracefully.
    """
    shost, sport = _check_target(socks_host, socks_port)
    thost, tport = _check_target(target_host, target_port)
    _check_credentials(username, password)
    fwd = UdpForwarderViaSocks5(
        socks_host=shost, socks_port=sport, target_host=thost, target_port=tport,
        username=username, password=password, handshake_timeout=handshake_timeout,
        connect_timeout=connect_timeout, use_server_address=use_server_address,
        max_sessions=max_sessions, verbose=verbose, block_list=(), dns_timeout=10.0,
        idle_timeout=idle_timeout, close_timeout=close_timeout, resolver=None,
    )
    await fwd._start(listen_addr, listen_port)
    return fwd


# --------------------------------------------------------------------------- #
# Command line
# --------------------------------------------------------------------------- #
def _hostport(text: str) -> Tuple[str, int]:
    host, sep, port = text.rpartition(":")
    if not sep or not port.isdigit():
        raise argparse.ArgumentTypeError(f"expected HOST:PORT, got {text!r}")
    return host.strip("[]"), int(port)


def main(argv: Optional[Sequence[str]] = None) -> int:
    p = argparse.ArgumentParser(description="SOCKS5 server and TCP/UDP port forwarders")
    sub = p.add_subparsers(dest="mode", required=True)

    def common(sp, default_port, block=True):
        sp.add_argument("--bind", default="127.0.0.1", help="listen address (default 127.0.0.1)")
        sp.add_argument("--port", type=int, default=default_port, help="listen port")
        sp.add_argument("-v", "--verbose", action="store_true", help="log connections to stdout")
        if block:
            sp.add_argument("--block", action="append", default=[], metavar="CIDR_OR_HOST",
                            help="blocked destination (repeatable)")

    def via(sp):
        sp.add_argument("--socks", required=True, type=_hostport, metavar="HOST:PORT",
                        help="upstream SOCKS5 server")
        sp.add_argument("--target", required=True, type=_hostport, metavar="HOST:PORT",
                        help="destination, as seen from the SOCKS5 server")
        sp.add_argument("--user", help="SOCKS5 username")
        sp.add_argument("--password", default=os.environ.get("SOCKS5_PASSWORD"),
                        help="SOCKS5 password (default: $SOCKS5_PASSWORD)")

    s = sub.add_parser("socks5", help="run a SOCKS5 server")
    common(s, 1080)
    s.add_argument("--no-default-block", action="store_true",
                   help="do not block loopback destinations by default")
    s.add_argument("--idle-timeout", type=float, default=300.0)
    s.add_argument("--max-connections", type=int, default=1024)

    t = sub.add_parser("tcp", help="forward TCP connections to a fixed target")
    common(t, 8080)
    t.add_argument("--target", required=True, type=_hostport, metavar="HOST:PORT")
    t.add_argument("--idle-timeout", type=float, default=300.0)
    t.add_argument("--max-connections", type=int, default=1024)

    u = sub.add_parser("udp", help="forward UDP datagrams to a fixed target")
    common(u, 5353)
    u.add_argument("--target", required=True, type=_hostport, metavar="HOST:PORT")
    u.add_argument("--idle-timeout", type=float, default=60.0)
    u.add_argument("--max-sessions", type=int, default=1024)

    vt = sub.add_parser("tcp-via-socks5", help="forward TCP connections to a target through a SOCKS5 server")
    common(vt, 8080, block=False)
    via(vt)
    vt.add_argument("--idle-timeout", type=float, default=300.0)
    vt.add_argument("--max-connections", type=int, default=1024)

    vu = sub.add_parser("udp-via-socks5", help="forward UDP datagrams to a target through a SOCKS5 server")
    common(vu, 5353, block=False)
    via(vu)
    vu.add_argument("--use-server-address", action="store_true",
                    help="always send UDP to the SOCKS5 server's own address")
    vu.add_argument("--idle-timeout", type=float, default=60.0)
    vu.add_argument("--max-sessions", type=int, default=1024)

    args = p.parse_args(argv)

    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    if args.mode == "socks5":
        block = list(() if args.no_default_block else DEFAULT_BLOCK_LIST) + args.block
        coro = serve_socks5(args.bind, args.port, verbose=args.verbose, block_list=block,
                            idle_timeout=args.idle_timeout, max_connections=args.max_connections)
    elif args.mode == "tcp":
        coro = forward_tcp(args.bind, args.port, *args.target, verbose=args.verbose,
                           block_list=args.block, idle_timeout=args.idle_timeout,
                           max_connections=args.max_connections)
    elif args.mode == "udp":
        coro = forward_udp(args.bind, args.port, *args.target, verbose=args.verbose,
                           block_list=args.block, idle_timeout=args.idle_timeout,
                           max_sessions=args.max_sessions)
    elif args.mode == "tcp-via-socks5":
        coro = forward_tcp_via_socks5(args.bind, args.port, *args.socks, *args.target,
                                      username=args.user, password=args.password,
                                      verbose=args.verbose, idle_timeout=args.idle_timeout,
                                      max_connections=args.max_connections)
    else:
        coro = forward_udp_via_socks5(args.bind, args.port, *args.socks, *args.target,
                                      username=args.user, password=args.password,
                                      verbose=args.verbose, idle_timeout=args.idle_timeout,
                                      max_sessions=args.max_sessions,
                                      use_server_address=args.use_server_address)
    try:
        handle = loop.run_until_complete(coro)
    except (OSError, ValueError) as exc:  # e.g. port already in use, bad host name
        print(f"{p.prog}: cannot start: {exc}", file=sys.stderr)
        loop.run_until_complete(loop.shutdown_asyncgens())
        loop.close()
        return 1
    for sig in (signal.SIGINT, signal.SIGTERM):
        try:
            loop.add_signal_handler(sig, loop.stop)
        except (NotImplementedError, RuntimeError, ValueError):
            pass  # e.g. Windows
    try:
        loop.run_forever()
    except KeyboardInterrupt:
        pass
    finally:
        loop.run_until_complete(handle.close())
        loop.run_until_complete(loop.shutdown_asyncgens())
        loop.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())
